from typing import List


class Solution:
    def makeStringGood(self, s: str) -> int:
        count = [0] * 26
        for ch in s:
            count[ord(ch) - 97] += 1
        best = len(s)
        for t in range(1, max(count) + 1):
            dp = [float("inf")] * 27
            dp[0] = 0
            for i in range(26):
                c = count[i]
                single = min(c, abs(c - t))
                if dp[i] + single < dp[i + 1]:
                    dp[i + 1] = dp[i] + single
                if i + 1 < 26 and count[i + 1] < t:
                    deficit = t - count[i + 1]
                    excess = c - t if c > t else c
                    pair = max(excess, deficit)
                    if dp[i] + pair < dp[i + 2]:
                        dp[i + 2] = dp[i] + pair
            best = min(best, dp[26])
        return best

